-- 0012 The whole resort catalog, for the resort picker.
--
-- Until now a resort existed for the app only once the pipeline had published
-- a bundle for it, so the picker could not say "this mountain is coming": it
-- showed nothing. This adds where each resort is (region, country), seeds the
-- catalog from pipeline/resorts.yaml, and opens a read-only list of every
-- resort with its active bundle (null while no map is published).
--
-- `resorts` itself stays as it was: clients still see only published rows
-- there, and everything that guards a write (profile_update, presence_update,
-- meet_propose) still requires `published`.

alter table public.resorts
  add column region text,     -- state or province code in the USA and Canada, else the country code
  add column country text;

-- The pipeline owns a row's other columns once it publishes the resort, so an
-- existing row only gains its region and country here.
on conflict (id) do update
  set region = excluded.region, country = excluded.country;

-- Every resort, published or not. `bundle_id`, `published_at` and `built_at`
-- are null until the resort has a map. Catalog metadata only: nothing here is
-- about a user. The view runs with its owner's rights on purpose (it is the
-- one read that must see unpublished rows); it exposes no column the public
-- website would not.
create view public.resort_catalog with (security_invoker = false) as
  select r.id, r.name, r.timezone, r.bbox, r.center, r.camera, r.pass_products,
         r.status_provider, r.status_mode, r.review_minutes, r.region, r.country,
         ab.bundle_id, ab.published_at, b.built_at
  from public.resorts r
  left join public.resort_active_bundle ab on ab.resort_id = r.id and r.published
  left join public.resort_bundles b on b.bundle_id = ab.bundle_id;

revoke all on public.resort_catalog from anon, authenticated;
grant select on public.resort_catalog to anon, authenticated;
